const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const sanJose = ee.Geometry.Point([-121.8863, 37.3382]).buffer(30000); // 30km radius around San Jose
  const juneStart = '2020-06-01';
  const juneEnd = '2020-06-30';
  const augustDate = '2020-08-26';
  const augustStart = '2020-08-20';
  const augustEnd = '2020-08-31';

  // Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Function to calculate NBR
  function addNBR(image) {
    const nbr = image.normalizedDifference(['B8', 'B12']).rename('NBR');
    return image.addBands(nbr);
  }

  // 2. Data Acquisition for June
  let juneCol = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(sanJose)
    .filterDate(juneStart, juneEnd)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
    .map(maskS2clouds)
    .map(addNBR);

  const juneSize = juneCol.size().getInfo();
  console.log(`June Images: ${juneSize}`);

  if (juneSize === 0) {
    console.log("No data for June 2020.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Data Acquisition for August
  let augustCol = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(sanJose)
    .filterDate(augustStart, augustEnd)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
    .map(maskS2clouds)
    .map(addNBR);

  const augustSize = augustCol.size().getInfo();
  console.log(`August Images: ${augustSize}`);

  if (augustSize === 0) {
    console.log("No data for August 2020.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Calculate median NBR for both periods
  const juneNBR = juneCol.select('NBR').median();
  const augustNBR = augustCol.select('NBR').median();

  // 5. Count valid pixels and burn scar pixels
  const juneStats = juneNBR.reduceRegion({
    reducer: ee.Reducer.count().combine({reducer2: ee.Reducer.mean(), sharedInputs: true}),
    geometry: sanJose,
    scale: 3000,
    maxPixels: 1e9
  });

  const juneCount = juneStats.get('NBR_count').getInfo();
  const juneMean = juneStats.get('NBR_mean').getInfo();

  console.log(`June Valid Pixels: ${juneCount}, Mean NBR: ${juneMean}`);

  if (juneCount === 0) {
    console.log("No valid pixels for June after masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  const augustStats = augustNBR.reduceRegion({
    reducer: ee.Reducer.count().combine({reducer2: ee.Reducer.mean(), sharedInputs: true}),
    geometry: sanJose,
    scale: 3000,
    maxPixels: 1e9
  });

  const augustCount = augustStats.get('NBR_count').getInfo();
  const augustMean = augustStats.get('NBR_mean').getInfo();

  console.log(`August Valid Pixels: ${augustCount}, Mean NBR: ${augustMean}`);

  if (augustCount === 0) {
    console.log("No valid pixels for August after masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 6. Count burn scar pixels (NBR < 0.1 indicates burned areas)
  const burnThreshold = 0.1;
  const juneBurns = juneNBR.lt(burnThreshold);
  const augustBurns = augustNBR.lt(burnThreshold);

  const juneBurnCount = juneBurns.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: sanJose,
    scale: 3000,
    maxPixels: 1e9
  }).get('NBR').getInfo();

  const augustBurnCount = augustBurns.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: sanJose,
    scale: 3000,
    maxPixels: 1e9
  }).get('NBR').getInfo();

  console.log(`June Burn Pixels: ${juneBurnCount}`);
  console.log(`August Burn Pixels: ${augustBurnCount}`);

  // 7. Validation & Final Answer
  if (juneBurnCount === null || augustBurnCount === null || 
      juneMean === null || augustMean === null ||
      isNaN(juneBurnCount) || isNaN(augustBurnCount)) {
    console.log("Calculation failed.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (augustBurnCount > juneBurnCount) {
    console.log("Burn scars expanded from June to August 2020.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Burn scars did not expand from June to August 2020.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
